var dateLeftMidnight = new Date(dateLeft)
dateLeftMidnight.setHours(0, 0, 0, 0)
var dateRightMidnight = new Date(dateRight)
dateRightMidnight.setHours(0, 0, 0, 0)

var result = Math.round((dateLeftMidnight - dateRightMidnight) / MILLISECONDS_IN_DAY)

if (result !== 0) {
  var dateRightPlusDays = new Date(dateRight)
  dateRightPlusDays.setDate(dateRightPlusDays.getDate() + result)
  if (result > 0 && dateLeft < dateRightPlusDays) result--
  else if (result < 0 && dateLeft > dateRightPlusDays) result++
}

return result

